(window.LESSONS=window.LESSONS||{}).obj={disc:'Синтаксис',t:'Дополнение',
th:`<h2>Дополнение</h2><div class="note"><b>Знакомство.</b> <i>Читаю книгу, помогаю брату, любуюсь закатом</i> — дополнение называет предмет, на который направлено действие. После урока вы сможете находить дополнения, различать прямые и косвенные и не путать их с подлежащим и обстоятельством.</div>
<h3>Что это</h3><p><b>Дополнение</b> — второстепенный член предложения, который обозначает предмет, на который направлено действие, или связанный с ним. Отвечает на вопросы <b>косвенных падежей</b>: кого? чего? кому? чему? кем? чем? о ком? о чём? Подчёркивается <b>пунктиром</b>.</p>
<h3>Виды</h3><table><tr><th>Вид</th><th>Как выражено</th><th>Примеры</th></tr><tr><td>Прямое</td><td>винительный падеж без предлога при переходном глаголе; родительный падеж при отрицании и обозначении части</td><td>читаю <i>книгу</i>; не читал <i>книги</i>; выпил <i>воды</i></td></tr><tr><td>Косвенное</td><td>остальные падежи, часто с предлогом</td><td>помогаю <i>брату</i>; любуюсь <i>закатом</i>; думаю <i>о друге</i></td></tr></table>
<h3>Чем выражено</h3><p>Существительным (<i>читаю книгу</i>), местоимением (<i>помог ему</i>), инфинитивом (<i>попросил помочь</i>), словосочетанием.</p>
<h3>Как отличить от других членов</h3><p><b>Подлежащее</b> — именительный падеж: <i>Мне нравится <u>музыка</u></i> («музыка» — подлежащее, «мне» — дополнение). <b>Обстоятельство</b> отвечает на вопросы где? когда? как? куда? почему?: <i>Читаю <u>дома</u></i>.</p>`,
ex:[['Я читаю книгу.','«Книгу» отвечает на вопрос «что?», винительный падеж без предлога при переходном глаголе.','Дополнение, прямое.'],['Я помогаю брату.','«Брату» отвечает на вопрос «кому?», дательный падеж.','Дополнение, косвенное.'],['Я любуюсь закатом.','«Закатом» отвечает на вопрос «чем?», творительный падеж.','Дополнение, косвенное.'],['Он не читал книги.','При отрицании вместо винительного падежа употреблён родительный. Всё равно прямое дополнение.','Дополнение, прямое (родительный падеж при отрицании).'],['Я прошу помочь.','«Помочь» — инфинитив, отвечает на вопрос «о чём?».','Дополнение, выраженное инфинитивом.']],
exr:[['Дополнение отвечает на вопросы',['косвенных падежей','кто? что?','где? когда?'],0,'Кого? чего? кому? чему?'],['Дополнение в «Я читаю книгу.» —',['книгу','читаю','я'],0,'Читаю (что?) книгу.'],['Прямое дополнение —',['читаю книгу','помогаю брату','любуюсь закатом'],0,'Винительный падеж без предлога.'],['Косвенное дополнение —',['помогаю брату','читаю книгу','пью воду'],0,'Дательный падеж.'],['Дополнение подчёркивается',['пунктиром','волнистой линией','двумя чертами'],0,'Пунктиром.'],['Дополнение в «Он думает о друге.» —',['о друге','думает','он'],0,'Думает (о ком?) о друге.'],['Дополнение в «Я прошу помочь.» выражено',['инфинитивом','существительным','наречием'],0,'Прошу (о чём?) помочь.'],['Дополнение в «Не читал книги» —',['прямое: Р. п. при отрицании','косвенное'],0,'Вместо винительного — родительный.'],['Падеж прямого дополнения при переходном глаголе —',['винительный','дательный','творительный'],0,'Винительный.'],['Дополнение в «Мне нравится музыка.» —',['мне','музыка'],0,'Музыка — подлежащее.']],
te:[['Дополнение обозначает',['предмет, на который направлено действие','признак предмета','место действия'],0,'Предмет.'],['Дополнение стоит в',['косвенном падеже','именительном падеже'],0,'Косвенном.'],['Дополнение в «Он помогает брату.» —',['брату','помогает'],0,'Помогает (кому?) брату.'],['Дополнение в «Он любуется закатом.» —',['закатом','любуется'],0,'Любуется (чем?) закатом.'],['Прямое дополнение —',['существительное в В. п. без предлога','существительное в П. п.','существительное в Т. п.'],0,'Винительный без предлога.'],['Дополнение в «Выпил воды» —',['воды','выпил'],0,'Прямое дополнение, Р. п. части.'],['Дополнение в «Попросил позвонить» —',['позвонить','попросил'],0,'Попросил (о чём?) позвонить.'],['Вопрос к дополнению в «Говорю о книге» —',['о чём?','где?','когда?'],0,'Предложный падеж.'],['Дополнение — это',['второстепенный член','главный член'],0,'Второстепенный.'],['Дополнение «ему» в «Я помог ему» выражено',['местоимением','инфинитивом','наречием'],0,'Личное местоимение.']],
sum:`<h3>Запомните</h3><ul><li>Дополнение — вопросы косвенных падежей. Подчёркивается пунктиром.</li><li>Прямое: В. п. без предлога (читаю книгу), Р. п. при отрицании (не читал книги).</li><li>Косвенное: все остальные.</li><li>Может быть выражено инфинитивом: прошу помочь.</li></ul><h3>Контрольные вопросы</h3><ol><li>Чем прямое дополнение отличается от косвенного?</li><li>Как отличить дополнение от подлежащего?</li><li>Как подчёркивается дополнение?</li></ol>`};

(window.LESSONS=window.LESSONS||{}).adv2={disc:'Синтаксис',t:'Обстоятельство',
th:`<h2>Обстоятельство</h2><div class="note"><b>Знакомство.</b> <i>Он быстро побежал домой.</i> Слова «быстро» и «домой» говорят, как и куда побежал мальчик. Это обстоятельства. После урока вы сможете находить обстоятельства и определять их вид.</div>
<h3>Что это</h3><p><b>Обстоятельство</b> — второстепенный член, который обозначает признак действия, состояния или другого признака. Отвечает на вопросы <i>где? куда? откуда? когда? как? почему? зачем?</i> Подчёркивается <b>точками и тире</b> (штрих-пунктиром).</p>
<h3>Виды</h3><table><tr><th>Вид</th><th>Вопрос</th><th>Пример</th></tr><tr><td>Места</td><td>где? куда? откуда?</td><td>живёт <i>в городе</i>, идёт <i>домой</i></td></tr><tr><td>Времени</td><td>когда? как долго?</td><td>пришёл <i>утром</i>, спал <i>долго</i></td></tr><tr><td>Образа действия</td><td>как? каким образом?</td><td>говорит <i>тихо</i>, шёл <i>улыбаясь</i></td></tr><tr><td>Меры и степени</td><td>насколько? в какой степени?</td><td><i>очень</i> устал</td></tr><tr><td>Причины</td><td>почему?</td><td>не пришёл <i>из-за болезни</i></td></tr><tr><td>Цели</td><td>зачем? с какой целью?</td><td>пошёл <i>гулять</i></td></tr><tr><td>Условия</td><td>при каком условии?</td><td>приходи <i>при желании</i></td></tr><tr><td>Уступки</td><td>несмотря на что?</td><td>пошёл <i>несмотря на дождь</i></td></tr></table>
<h3>Чем выражено</h3><p>Наречием (<i>быстро</i>), существительным с предлогом или без (<i>в городе, утром</i>), деепричастием и оборотом (<i>шёл, улыбаясь</i>), инфинитивом (<i>пошёл гулять</i>), сравнительным оборотом (<i>кричал как гром</i>).</p>`,
ex:[['Он живёт в городе.','«В городе» отвечает на вопрос «где?».','Обстоятельство места.'],['Мы вернулись вечером.','«Вечером» отвечает на вопрос «когда?».','Обстоятельство времени.'],['Она говорила тихо.','«Тихо» отвечает на вопрос «как?».','Обстоятельство образа действия.'],['Он не пришёл из-за болезни.','«Из-за болезни» отвечает на вопрос «почему?».','Обстоятельство причины.'],['Мы пошли гулять.','«Гулять» (инфинитив) отвечает на вопрос «зачем?».','Обстоятельство цели.']],
exr:[['Обстоятельство отвечает на вопросы',['где? когда? как?','кто? что?','какой?'],0,'Где? когда? как?'],['Обстоятельство в «Он быстро побежал.» —',['быстро','побежал'],0,'Побежал (как?) быстро.'],['Обстоятельство места —',['живёт в городе','читает книгу','пришёл утром'],0,'Живёт (где?).'],['Обстоятельство времени —',['пришёл утром','идёт домой','работает усердно'],0,'Пришёл (когда?).'],['Обстоятельство образа действия —',['шёл, улыбаясь','пришёл вчера','живёт здесь'],0,'Шёл (как?) улыбаясь.'],['Обстоятельство причины —',['не пришёл из-за болезни','пошёл гулять','читает дома'],0,'Не пришёл (почему?).'],['Обстоятельство цели —',['пошёл гулять','пришёл вчера','живёт в доме'],0,'Пошёл (зачем?).'],['Обстоятельство уступки —',['несмотря на дождь','из-за дождя','при дожде'],0,'Несмотря на что?'],['Обстоятельство подчёркивается',['точками и тире','пунктиром','волнистой линией'],0,'Штрих-пунктиром.'],['Обстоятельство может быть выражено',['наречием, деепричастием','только глаголом','только прилагательным'],0,'Разные части речи.']],
te:[['Обстоятельство обозначает',['признак действия','предмет','признак предмета'],0,'Признак действия.'],['Обстоятельство в «Я иду домой.» —',['домой','иду'],0,'Иду (куда?) домой.'],['Обстоятельство в «Утром выпал снег.» —',['утром','снег'],0,'Выпал (когда?).'],['Вопрос обстоятельства цели —',['зачем?','почему?','когда?'],0,'Зачем?'],['Вопрос обстоятельства причины —',['почему?','зачем?','где?'],0,'Почему?'],['Обстоятельство условия «при желании» отвечает на вопрос',['при каком условии?','где?','почему?'],0,'При каком условии?'],['Обстоятельство меры и степени —',['очень устал','устал сегодня','устал дома'],0,'Насколько?'],['Деепричастный оборот в предложении —',['обстоятельство','подлежащее','определение'],0,'Обстоятельство образа действия.'],['Обстоятельство в «Она говорила тихо.» —',['тихо','говорила'],0,'Говорила (как?) тихо.'],['Обстоятельство в «Он живёт здесь.» —',['здесь','живёт'],0,'Живёт (где?) здесь.']],
sum:`<h3>Запомните</h3><ul><li>Обстоятельство — где? куда? когда? как? почему? зачем?</li><li>Виды: места, времени, образа действия, меры и степени, причины, цели, условия, уступки.</li><li>Подчёркивается штрих-пунктиром.</li><li>Может быть выражено наречием, существительным, деепричастием, инфинитивом.</li></ul><h3>Контрольные вопросы</h3><ol><li>Как отличить обстоятельство от дополнения?</li><li>Какие вопросы задают к обстоятельству причины и цели?</li><li>Какой частью речи выражено обстоятельство в предложении «Он шёл, улыбаясь»?</li></ol>`};

(window.LESSONS=window.LESSONS||{}).twopart={disc:'Синтаксис',t:'Двусоставные предложения',
th:`<h2>Двусоставные предложения</h2><div class="note"><b>Знакомство.</b> Большинство русских предложений состоят из подлежащего и сказуемого: <i>Дети играют. Наступила осень.</i> Это двусоставные предложения. После урока вы сможете отличать их от односоставных и определять порядок слов.</div>
<h3>Что это</h3><p><b>Двусоставное предложение</b> — предложение, в основе которого есть <b>оба главных члена</b>: подлежащее и сказуемое. Они могут быть и без второстепенных членов (нераспространённое): <i>Дети играют</i>, и с ними (распространённое): <i>Дети весело играют во дворе</i>.</p>
<h3>Полные и неполные</h3><p><b>Полные</b> — все необходимые члены есть. <b>Неполные</b> — какой-то член пропущен, но понятен из контекста или ситуации. Чаще всего это реплики диалога: <i>— Что ты читаешь? — Книгу.</i> Здесь пропущены и подлежащее, и сказуемое («я читаю»).</p>
<h3>Порядок слов</h3><p><b>Прямой</b> порядок: подлежащее перед сказуемым: <i>Осень наступила.</i> <b>Обратный</b> (инверсия): сказуемое перед подлежащим: <i>Наступила осень.</i> Обратный порядок часто придаёт предложению особую выразительность.</p>
<div class="note"><b>Как проверить.</b> Найдите подлежащее и сказуемое. Если нашли оба, предложение двусоставное. Если один главный член, предложение односоставное (<i>Светает. Тишина.</i>).</div>`,
ex:[['Мальчик читает.','Подлежащее «мальчик», сказуемое «читает». Других членов нет.','Двусоставное, нераспространённое.'],['Наступила осень.','Подлежащее «осень», сказуемое «наступила». Сказуемое стоит перед подлежащим.','Двусоставное; обратный порядок слов.'],['Мы живём в городе.','Подлежащее «мы», сказуемое «живём», есть обстоятельство «в городе».','Двусоставное, распространённое.'],['— Что ты читаешь? — Книгу.','Ответ «Книгу» — дополнение, подлежащее и сказуемое («я читаю») пропущены, но понятны из вопроса.','Неполное предложение.'],['Дети играют во дворе.','Подлежащее «дети», сказуемое «играют», обстоятельство «во дворе».','Двусоставное, распространённое; прямой порядок слов.']],
exr:[['Двусоставное предложение содержит',['подлежащее и сказуемое','только сказуемое','только подлежащее'],0,'Оба главных члена.'],['Двусоставное предложение —',['Мальчик читает.','Светает.','Холодно.'],0,'Подлежащее «мальчик».'],['Какое предложение неполное (ответ на вопрос «Что ты читаешь?»)?',['Книгу.','Я читаю книгу.','Читаю.'],0,'Пропущены подлежащее и сказуемое.'],['В неполном предложении',['пропущен член, понятный из контекста','нет основы','нет слов'],0,'Понятен из контекста.'],['«Наступила осень.» — порядок слов',['обратный','прямой'],0,'Сказуемое перед подлежащим.'],['«Дети играют.» — порядок слов',['прямой','обратный'],0,'Подлежащее перед сказуемым.'],['«Весна пришла.» по наличию второстепенных членов —',['нераспространённое','распространённое'],0,'Только главные члены.'],['Какое предложение двусоставное?',['Дует ветер.','Дует.','Темнеет.'],0,'Подлежащее «ветер».'],['Реплика «В магазин» в ответ на «Куда ты идёшь?» —',['неполное предложение','полное предложение'],0,'Пропущено «я иду».'],['Двусоставное предложение может быть',['распространённым и нераспространённым','только распространённым'],0,'Бывает и таким, и другим.']],
te:[['Подлежащее и сказуемое есть в',['двусоставном предложении','односоставном','любом'],0,'Двусоставное.'],['Двусоставное предложение —',['Ночь прошла.','Светает.'],0,'Подлежащее «ночь».'],['Неполное предложение (ответ на «Куда ты идёшь?») —',['В магазин.','Я иду в магазин.'],0,'Пропущены подлежащее и сказуемое.'],['Прямой порядок слов — когда',['подлежащее стоит перед сказуемым','сказуемое перед подлежащим'],0,'Подлежащее перед сказуемым.'],['Обратный порядок слов в',['Наступила зима.','Зима наступила.'],0,'Сказуемое перед подлежащим.'],['Что пропущено в ответе «В магазин» на вопрос «Куда ты идёшь?»?',['подлежащее и сказуемое','определение'],0,'«Я иду».'],['Двусоставное нераспространённое —',['Дождь идёт.','Мелкий дождь идёт.'],0,'Нет второстепенных членов.'],['Подлежащее в «Идёт дождь.» —',['дождь','идёт'],0,'Что идёт?'],['В двусоставном предложении главных членов',['два','один'],0,'Два.'],['«Мы живём в городе.» — двусоставное, потому что',['есть подлежащее «мы» и сказуемое «живём»','нет сказуемого'],0,'Есть оба главных члена.']],
sum:`<h3>Запомните</h3><ul><li>Двусоставное предложение: подлежащее + сказуемое.</li><li>Полные и неполные; нераспространённые и распространённые.</li><li>Прямой порядок: подлежащее — сказуемое; обратный — наоборот.</li></ul><h3>Контрольные вопросы</h3><ol><li>Чем двусоставное предложение отличается от односоставного?</li><li>Что такое неполное предложение?</li><li>Что такое обратный порядок слов?</li></ol>`};

(window.LESSONS=window.LESSONS||{}).onepart={disc:'Синтаксис',t:'Односоставные предложения',
th:`<h2>Односоставные предложения</h2><div class="note"><b>Знакомство.</b> <i>Иду домой. В дверь стучат. Светает. Ночь.</i> В этих предложениях только один главный член: сказуемое или подлежащее. После урока вы сможете определять вид односоставных предложений.</div>
<h3>Что это</h3><p><b>Односоставное предложение</b> — предложение, в основе которого <b>один главный член</b>. Второй не нужен и обычно не может быть назван. Односоставные предложения — не «неполные»: смысл в них полный.</p>
<h3>Виды</h3><table><tr><th>Вид</th><th>Особенность</th><th>Пример</th></tr><tr><td>Определённо-личное</td><td>сказуемое — глагол 1-го или 2-го лица, деятель понятен (я, ты, мы, вы)</td><td><i>Иду</i> домой. <i>Люблю</i> грозу в начале мая.</td></tr><tr><td>Неопределённо-личное</td><td>глагол 3-го лица мн. числа или прошедшего времени мн. числа; деятель неизвестен или неважен</td><td>В дверь <i>стучат</i>. Мне <i>принесли</i> письмо.</td></tr><tr><td>Обобщённо-личное</td><td>действие относится к любому человеку (пословицы)</td><td><i>Любишь</i> кататься — <i>люби</i> и саночки возить.</td></tr><tr><td>Безличное</td><td>подлежащего нет и быть не может</td><td><i>Светает. Мне холодно. Не спится.</i></td></tr><tr><td>Назывное</td><td>главный член — подлежащее, называет существование предмета</td><td><i>Ночь. Улица. Фонарь.</i></td></tr></table>
<h3>Как отличить</h3><p>Если можно добавить «я/ты/мы/вы», это определённо-личное. Если подходит «кто-то, они» (деятель неизвестен), это неопределённо-личное. Если подлежащее добавить невозможно (<i>Светает, Мне холодно</i>), это безличное.</p>`,
ex:[['Иду домой.','Глагол 1-го лица, можно добавить «я». Деятель понятен.','Определённо-личное.'],['В дверь стучат.','Глагол 3-го лица мн. числа, но «они» подставить нельзя: деятель неизвестен.','Неопределённо-личное.'],['Любишь кататься — люби и саночки возить.','Глагол во 2-м лице, смысл относится к любому человеку (пословица).','Обобщённо-личное.'],['Светает.','Подлежащее подставить нельзя. Нет деятеля.','Безличное.'],['Ночь. Улица. Фонарь.','В предложениях только подлежащее, они называют предметы.','Назывные.']],
exr:[['Односоставное предложение содержит',['один главный член','подлежащее и сказуемое','два сказуемых'],0,'Один главный член.'],['Определённо-личное предложение —',['Иду домой.','В дверь стучат.','Светает.'],0,'Можно добавить «я».'],['Неопределённо-личное предложение —',['В дверь стучат.','Иду домой.','Ночь.'],0,'Деятель неизвестен.'],['Безличное предложение —',['Светает.','Иду домой.','Ночь.'],0,'Нет подлежащего.'],['Назывное предложение —',['Ночь. Улица. Фонарь.','Светает.','Иду.'],0,'Называет предметы.'],['Обобщённо-личное предложение —',['Любишь кататься — люби и саночки возить.','Мне холодно.','Тишина.'],0,'Пословица, относится к любому человеку.'],['Сказуемое в определённо-личном предложении — глагол',['1-го или 2-го лица','3-го лица мн. числа','безличный глагол'],0,'Иду, идёшь.'],['В безличном предложении подлежащее',['нет и быть не может','есть'],0,'Нет.'],['В назывном предложении главный член —',['подлежащее','сказуемое'],0,'Подлежащее.'],['«Мне не спится.» —',['безличное','определённо-личное'],0,'Нет подлежащего.']],
te:[['Тип предложения «Вижу море.» —',['определённо-личное','неопределённо-личное','безличное'],0,'Можно добавить «я».'],['«Мне принесли письмо.» —',['неопределённо-личное','определённо-личное','безличное'],0,'Кто принёс — неизвестно.'],['«Светает.» —',['безличное','назывное'],0,'Нет подлежащего.'],['«Тишина.» —',['назывное','безличное'],0,'Подлежащее без сказуемого.'],['«Что посеешь, то и пожнёшь.» —',['обобщённо-личное','определённо-личное','назывное'],0,'Пословица.'],['Безличные глаголы',['не имеют подлежащего','имеют подлежащее'],0,'Деятеля нет.'],['«Мне холодно» — безличное, потому что сказуемое выражено',['категорией состояния','глаголом 1-го лица'],0,'«Холодно» — категория состояния.'],['Какое предложение двусоставное?',['Он идёт домой.','Иду домой.'],0,'Есть подлежащее «он».'],['В неопределённо-личном предложении деятель',['неизвестен или не важен','назван подлежащим'],0,'Неизвестен.'],['Назывное предложение утверждает',['существование предмета','действие','признак'],0,'Существование предмета.']],
sum:`<h3>Запомните</h3><ul><li>Односоставное предложение: один главный член.</li><li>Определённо-личное, неопределённо-личное, обобщённо-личное, безличное, назывное.</li><li>Безличные предложения: подлежащего нет и быть не может.</li><li>Назывные: главный член — подлежащее.</li></ul><h3>Контрольные вопросы</h3><ol><li>Чем безличное предложение отличается от неопределённо-личного?</li><li>Какое предложение называется назывным?</li><li>Как отличить односоставное предложение от неполного двусоставного?</li></ol>`};

(window.LESSONS=window.LESSONS||{}).homog={disc:'Синтаксис',t:'Однородные члены предложения',
th:`<h2>Однородные члены предложения</h2><div class="note"><b>Знакомство.</b> <i>Я купил хлеб, молоко и сыр.</i> Слова «хлеб», «молоко», «сыр» отвечают на один вопрос и выполняют одну роль — это однородные члены. После урока вы сможете находить их и правильно ставить запятые.</div>
<h3>Что это</h3><p><b>Однородные члены</b> — члены предложения, которые отвечают на <b>один и тот же вопрос</b>, относятся к одному слову, выполняют одну синтаксическую функцию и связаны <b>сочинительной связью</b> (союзами или интонацией перечисления). Однородными могут быть любые члены: подлежащие, сказуемые, дополнения, определения, обстоятельства.</p>
<h3>Связь и запятые</h3><table><tr><th>Связь</th><th>Правило</th><th>Пример</th></tr><tr><td>Без союзов</td><td>запятая</td><td>Купил <i>хлеб, молоко, сыр</i>.</td></tr><tr><td>Одиночный союз «и», «да» (= и), «или», «либо»</td><td>запятая не нужна</td><td>Купил хлеб <i>и</i> молоко.</td></tr><tr><td>Повторяющийся союз «и…и», «или…или», «ни…ни»</td><td>запятая перед каждым, кроме первого</td><td><i>И</i> дождь, <i>и</i> снег. <i>Ни</i> дождь, <i>ни</i> снег.</td></tr><tr><td>Противительные «а, но, зато»</td><td>запятая всегда</td><td>Он умён, <i>но</i> ленив.</td></tr></table>
<h3>Обобщающие слова</h3><p>Если перед однородными членами стоит обобщающее слово, после него ставится <b>двоеточие</b>: <i>Всё было здесь: и поле, и лес.</i> Если обобщающее слово после, перед ним ставится <b>тире</b>: <i>Дети, взрослые — все пошли.</i></p>
<h3>Однородные и неоднородные определения</h3><p>Однородные определения характеризуют предмет с одной стороны, между ними можно поставить «и»: <i>большой, красивый дом</i> (запятая). Неоднородные — с разных сторон: <i>красивый каменный дом</i> (запятой нет).</p>`,
ex:[['Я купил хлеб, молоко, сыр.','Три дополнения отвечают на вопрос «что?», связаны перечислением без союзов, запятая между ними.','Однородные дополнения; запятые.'],['Я купил хлеб и молоко.','Одиночный союз «и» соединяет два дополнения. Запятая не нужна.','Однородные дополнения; без запятой.'],['И дождь, и снег шли весь день.','Повторяющийся союз «и…и»: запятая перед вторым «и».','Однородные подлежащие; запятая.'],['Он умён, но ленив.','Противительный союз «но»: запятая обязательна.','Однородные сказуемые; запятая.'],['Всё было здесь: и поле, и лес.','Обобщающее слово «всё» стоит перед однородными членами, после него двоеточие.','Однородные члены; обобщающее слово; двоеточие.']],
exr:[['Однородные члены отвечают на',['один вопрос','разные вопросы','вопрос «кто?» только'],0,'Один вопрос.'],['Однородные члены в «Я купил хлеб, молоко и сыр.» —',['хлеб, молоко, сыр','купил, хлеб'],0,'Все — дополнения.'],['Нужна ли запятая: «Я купил хлеб и молоко.»?',['нет','да'],0,'Одиночный союз «и».'],['Как правильно?',['И дождь, и снег шли.','И дождь и снег шли.'],0,'Повторяющийся союз.'],['Запятая перед «но» между однородными членами',['нужна','не нужна'],0,'Всегда.'],['Однородные определения —',['большой, красивый дом','красивый каменный дом'],0,'С одной стороны.'],['Знак после обобщающего слова перед однородными членами —',['двоеточие','тире'],0,'Двоеточие.'],['Знак после однородных членов перед обобщающим словом —',['тире','двоеточие'],0,'Тире.'],['Верно:',['Всё было здесь: и поле, и лес.','Всё было здесь, и поле, и лес.'],0,'Двоеточие после обобщающего слова.'],['Однородные члены соединяются',['сочинительной связью','подчинительной'],0,'Сочинительной.']],
te:[['Однородные члены могут быть',['любыми членами предложения','только подлежащими'],0,'Любыми.'],['Нет запятой в',['Купил хлеб и молоко.','Купил хлеб, молоко.'],0,'Одиночный «и».'],['Верно:',['Он умён, но ленив.','Он умён но ленив.'],0,'Перед «но» запятая.'],['Верно:',['Не снег, а дождь шёл.','Не снег а дождь шёл.'],0,'Перед «а» запятая.'],['Верно:',['Ни дождь, ни снег не остановят.','Ни дождь ни снег не остановят.'],0,'Повторяющийся «ни».'],['Верно:',['Все: и дети, и взрослые — пошли.','Все, и дети, и взрослые — пошли.'],0,'После обобщающего слова двоеточие.'],['Неоднородные определения —',['красивый каменный дом','большой красивый дом'],0,'Характеризуют с разных сторон.'],['Верно:',['Там росли дубы, клёны, берёзы.','Там росли дубы клёны берёзы.'],0,'Перечисление — запятые.'],['Верно:',['Дети, взрослые — все пошли.','Дети взрослые: все пошли.'],0,'Перед обобщающим словом тире.'],['Однородные члены отвечают на',['один вопрос и зависят от одного слова','разные вопросы'],0,'Один вопрос.']],
sum:`<h3>Запомните</h3><ul><li>Однородные члены отвечают на один вопрос и связаны сочинительной связью.</li><li>Без союзов — запятая; одиночный «и» — без запятой; повторяющийся — с запятой.</li><li>Перед «а, но, зато» запятая всегда.</li><li>Обобщающее слово: двоеточие после него, тире перед ним.</li></ul><h3>Контрольные вопросы</h3><ol><li>Когда перед «и» запятая не нужна?</li><li>Какие определения называют однородными?</li><li>Какие знаки ставятся с обобщающим словом?</li></ol>`};

(window.LESSONS=window.LESSONS||{}).address={disc:'Синтаксис',t:'Обращения',
th:`<h2>Обращения</h2><div class="note"><b>Знакомство.</b> <i>Мама, иди сюда! Друзья, добро пожаловать!</i> Слова «мама» и «друзья» называют тех, к кому мы обращаемся. После урока вы сможете находить обращения и правильно ставить знаки препинания.</div>
<h3>Что это</h3><p><b>Обращение</b> — слово или сочетание слов, называющее того, к кому обращена речь. Обращение <b>не является членом предложения</b> и грамматически не связано с другими словами. Оно произносится с особой звательной интонацией.</p>
<h3>Чем выражено</h3><p>Существительным в именительном падеже (<i>Мама, иди сюда!</i>), прилагательным, причастием, местоимением в роли существительного (<i>Эй, ты, постой!</i>). Обращение может быть распространённым: <i>Дорогие друзья, добро пожаловать!</i></p>
<h3>Место и знаки препинания</h3><table><tr><th>Место</th><th>Знаки</th><th>Пример</th></tr><tr><td>В начале</td><td>запятая после</td><td>Саша, иди сюда.</td></tr><tr><td>В середине</td><td>запятые с двух сторон</td><td>Я думаю, друг мой, что ты прав.</td></tr><tr><td>В конце</td><td>запятая перед</td><td>Иди сюда, Саша.</td></tr><tr><td>Сильная эмоция</td><td>восклицательный знак после</td><td>Саша! Иди сюда.</td></tr></table>
<div class="note"><b>Не путайте с подлежащим.</b> <i>Мама пришла.</i> — «мама» подлежащее, запятых нет. <i>Мама, иди сюда!</i> — «мама» обращение. Проверка: обращение можно убрать, а основа предложения останется.</div>`,
ex:[['Мама, иди сюда!','Слово «мама» называет того, к кому обращаются. Стоит в начале, после него запятая.','Обращение в начале предложения.'],['Иди сюда, Саша.','«Саша» в конце предложения: запятая ставится перед обращением.','Обращение в конце предложения.'],['Я думаю, друг мой, что ты прав.','«Друг мой» стоит внутри предложения и выделяется запятыми с двух сторон.','Распространённое обращение в середине предложения.'],['Дорогие друзья, добро пожаловать!','«Дорогие друзья» — обращение с определением, после него запятая.','Распространённое обращение.'],['Мама пришла.','«Мама» — подлежащее: отвечает на вопрос «кто пришёл?». Запятых нет.','Не обращение: подлежащее.']],
exr:[['Обращение называет',['того, к кому обращена речь','предмет разговора','признак предмета'],0,'Того, к кому обращена речь.'],['Обращение в «Мама, иди сюда!» —',['мама','иди'],0,'К маме обращаются.'],['Обращение — член предложения?',['нет','да'],0,'Не является членом предложения.'],['Верно:',['Саша, иди сюда.','Саша иди сюда.'],0,'После обращения запятая.'],['Верно:',['Иди сюда, Саша.','Иди сюда Саша.'],0,'Перед обращением запятая.'],['Верно:',['Я думаю, друг мой, что ты прав.','Я думаю друг мой, что ты прав.'],0,'Обращение выделяется с двух сторон.'],['Обращение в «Дорогие друзья, добро пожаловать!» —',['дорогие друзья','пожаловать'],0,'Распространённое обращение.'],['«Мама пришла.» — слово «мама»',['подлежащее','обращение'],0,'Кто пришёл?'],['Обращение выделяется',['запятыми','тире','скобками'],0,'Запятыми.'],['Обращение выражено',['существительным в И. п.','глаголом','наречием'],0,'Существительным в именительном падеже.']],
te:[['В «Друг мой, помоги мне.» обращение —',['друг мой','помоги'],0,'К другу обращаются.'],['Верно:',['Здравствуй, друг!','Здравствуй друг!'],0,'Запятая после «Здравствуй».'],['Верно:',['Расскажи, Маша, что случилось.','Расскажи Маша что случилось.'],0,'Обращение выделяется запятыми.'],['Обращение в «Эй, ты, постой!» —',['ты','постой'],0,'Обращаются к «ты».'],['Обращение стоит',['в начале, в середине или в конце','только в начале'],0,'В любом месте.'],['Знак после обращения в начале при спокойной интонации —',['запятая','двоеточие'],0,'Запятая.'],['Если обращение произносится с восклицанием, то после него ставится',['восклицательный знак','двоеточие'],0,'Восклицательный знак.'],['Обращение может быть выражено',['существительным или местоимением','только наречием'],0,'Существительным или местоимением.'],['В «Мама, я пришёл!» подлежащее —',['я','мама'],0,'«Мама» — обращение.'],['«Иван пришёл.» — слово «Иван»',['подлежащее','обращение'],0,'Кто пришёл?']],
sum:`<h3>Запомните</h3><ul><li>Обращение называет того, к кому обращена речь, и не является членом предложения.</li><li>Выделяется запятыми (или восклицательным знаком).</li><li>Может стоять в начале, середине, конце.</li><li>Не путайте с подлежащим.</li></ul><h3>Контрольные вопросы</h3><ol><li>Как отличить обращение от подлежащего?</li><li>Какими знаками выделяется обращение в середине предложения?</li><li>Чем может быть выражено обращение?</li></ol>`};

(window.LESSONS=window.LESSONS||{}).intro={disc:'Синтаксис',t:'Вводные слова',
th:`<h2>Вводные слова</h2><div class="note"><b>Знакомство.</b> <i>К счастью, мы успели. Он, конечно, придёт.</i> Слова «к счастью» и «конечно» показывают, как говорящий относится к сказанному. Это вводные слова. После урока вы сможете находить их и правильно ставить запятые.</div>
<h3>Что это</h3><p><b>Вводные слова</b> и сочетания выражают <b>отношение говорящего к высказыванию</b>, не являются членами предложения и не связаны с ними грамматически. Их можно убрать без нарушения смысла и строя. На письме выделяются <b>запятыми</b>.</p>
<h3>Значения</h3><table><tr><th>Значение</th><th>Примеры</th></tr><tr><td>Уверенность</td><td>конечно, безусловно, разумеется, без сомнения</td></tr><tr><td>Неуверенность</td><td>кажется, возможно, вероятно, по-видимому, наверное, может быть</td></tr><tr><td>Чувства</td><td>к счастью, к сожалению, к удивлению</td></tr><tr><td>Источник сообщения</td><td>по-моему, по словам..., говорят, по мнению...</td></tr><tr><td>Порядок мыслей, связь</td><td>во-первых, итак, значит, например, кстати, в частности</td></tr><tr><td>Привлечение внимания</td><td>послушайте, знаете, представьте</td></tr></table>
<h3>Знаки препинания</h3><p>Вводное слово выделяется запятыми с двух сторон: <i>Он, конечно, придёт.</i> В начале — запятая после: <i>К сожалению, я опоздал.</i> В конце — запятая перед.</p>
<div class="note"><b>Не вводные слова</b> (запятыми не выделяются): <i>вряд ли, будто, как бы, якобы, словно, почти, даже, только, ведь, зато</i>.</div>`,
ex:[['К счастью, мы успели.','«К счастью» выражает чувство радости, можно убрать без изменения смысла. После слова запятая.','Вводное сочетание (чувства).'],['Он, конечно, придёт.','«Конечно» выражает уверенность, выделено запятыми с двух сторон.','Вводное слово (уверенность).'],['Возможно, пойдёт дождь.','«Возможно» выражает неуверенность.','Вводное слово (неуверенность).'],['По-моему, он прав.','«По-моему» указывает на источник мнения.','Вводное сочетание (источник сообщения).'],['Во-первых, надо отдохнуть.','«Во-первых» указывает на порядок мыслей.','Вводное слово (порядок мыслей).']],
exr:[['Вводное слово —',['к счастью','красиво','быстро'],0,'«К счастью» выражает отношение.'],['Вводные слова выделяются',['запятыми','тире','кавычками'],0,'Запятыми.'],['Вводное слово выражает',['отношение говорящего к сказанному','действие','признак'],0,'Отношение говорящего.'],['Вводное слово в «К счастью, мы успели.» —',['к счастью','успели'],0,'«К счастью».'],['Вводное слово со значением уверенности —',['конечно','кажется','возможно'],0,'Конечно.'],['Вводное слово со значением неуверенности —',['возможно','конечно','безусловно'],0,'Возможно.'],['Вводное слово со значением порядка мыслей —',['во-первых','кажется','к удивлению'],0,'Во-первых.'],['Вводное слово со значением источника сообщения —',['по-моему','конечно','к счастью'],0,'По-моему.'],['Не является вводным —',['вряд ли','наверное','кстати'],0,'«Вряд ли» — частица.'],['Вводное слово — член предложения?',['нет','да'],0,'Не член предложения.']],
te:[['Верно:',['Он, конечно, придёт.','Он конечно придёт.'],0,'Запятые с двух сторон.'],['Верно:',['К сожалению, я опоздал.','К сожалению я опоздал.'],0,'Запятая после вводного сочетания.'],['«Наверное, вероятно» выражают',['неуверенность','уверенность','чувства'],0,'Неуверенность.'],['«К счастью, к удивлению» выражают',['чувства','неуверенность','источник'],0,'Чувства.'],['«Например» выражает',['связь мыслей','уверенность','чувства'],0,'Связь мыслей.'],['Верно:',['Мы, например, поедем на море.','Мы например, поедем на море.'],0,'Выделяется с двух сторон.'],['Не вводное слово —',['будто','кажется','по-видимому'],0,'«Будто» — союз или частица.'],['Верно:',['По-моему, он прав.','По моему он прав.'],0,'«По-моему» через дефис, запятая после.'],['Вводное слово можно',['убрать без нарушения смысла и строя','нельзя убрать'],0,'Его можно опустить.'],['Вводные слова стоят',['в начале, середине, конце','только в начале'],0,'В любом месте.']],
sum:`<h3>Запомните</h3><ul><li>Вводные слова выражают отношение говорящего и выделяются запятыми.</li><li>Значения: уверенность, неуверенность, чувства, источник, порядок мыслей.</li><li>Не вводные: вряд ли, будто, как бы, якобы, словно, почти, даже, только.</li></ul><h3>Контрольные вопросы</h3><ol><li>Чем вводные слова отличаются от членов предложения?</li><li>Какие значения выражают вводные слова?</li><li>Какие слова не являются вводными?</li></ol>`};